/**
 * CV template catalogue — scraped from FlowCV's public gallery
 * (https://flowcv.com/resume-templates).
 *
 * flowcvTemplates.json is generated by scripts/scrapeFlowcvTemplates.mjs and
 * holds each template's slug, display name, FlowCV category tags, the design
 * blurb published on its FlowCV page (some pages only ship a generic stub, in
 * which case we derive neutral copy from the tags), and its locally stored
 * preview image. The server validates slugs against the same scrape via
 * server/config/flowcvTemplateSlugs.json, so both sides stay in sync.
 */

import manifest from './flowcvTemplates.json';

/** FlowCV tag -> filter-chip label. */
const TAG_LABELS = {
  popular: 'Popular',
  simple: 'Simple',
  modern: 'Modern',
  creative: 'Creative',
  photo: 'Photo',
  compact: 'Compact',
  firstJob: 'First Job',
  classic: 'Classic',
  professional: 'Professional',
};

export const CATEGORIES = ['All', ...Object.values(TAG_LABELS)];

/** Neutral copy for templates whose FlowCV page publishes no per-template blurb. */
const TAG_PHRASES = {
  simple: 'a clean, simple structure',
  modern: 'a modern look',
  creative: 'creative styling',
  photo: 'photo support',
  compact: 'a compact, content-dense layout',
  firstJob: 'a structure aimed at first-job applicants',
};

const fallbackDescription = (tags) => {
  const phrases = tags
    .filter((tag) => tag !== 'popular')
    .map((tag) => TAG_PHRASES[tag])
    .filter(Boolean);
  if (phrases.length === 0) return 'Template design from the FlowCV gallery.';
  const list =
    phrases.length === 1
      ? phrases[0]
      : `${phrases.slice(0, -1).join(', ')} and ${phrases[phrases.length - 1]}`;
  return `FlowCV gallery template with ${list}.`;
};

export const TEMPLATES = manifest.map((entry) => ({
  slug: entry.slug,
  name: entry.name,
  image: entry.image,
  description: entry.design || fallbackDescription(entry.tags),
  categories: entry.tags.map((tag) => TAG_LABELS[tag]).filter(Boolean),
  formats: ['pdf'], // FlowCV templates download as PDF
  featured: entry.tags.includes('popular'),
  sourceUrl: `https://flowcv.com/resume-template/${entry.slug}`,
}));

export const TEMPLATE_SLUGS = TEMPLATES.map((t) => t.slug);

export const getTemplate = (slug) => TEMPLATES.find((t) => t.slug === slug) || null;

export const isKnownSlug = (slug) => TEMPLATE_SLUGS.includes(slug);
